sys_script_include.script:
function StartInterview(vBusinessProcess, vUser)
{
	var IsValidRecord = x_snc_devtools.IsValidRecord;
	var GetUserRecord = x_snc_devtools.GetUserRecord;
	var StartAgenticConversation = x_snc_devtools.StartAgenticConversation;
	var IsValidSysId = x_snc_devtools.IsValidSysId;

	var grBusinessProcess = GetBusinessProcessRecord(vBusinessProcess);
	if (IsValidRecord(grBusinessProcess) == false)
	{
		LogError('StartInterview: Business Process not found');
		return false;
	}

	var grUser = GetUserRecord(vUser);
	if (IsValidRecord(grUser) == false)
	{
		LogError('StartInterview: User not found');
		return false;
	}

	var strConversationSysId = StartAgenticConversation(
		'Agentic Business Process Consultant',
		'Start interview with user about business process '+grBusinessProcess.number,
		grBusinessProcess,
		grUser,
		true);

	if (IsValidSysId(strConversationSysId) == false)
	{
		LogError('StartInterview: conversation not started');
		return false;
	}

	return strConversationSysId;
}
